/*
 * A242482  Numbers n such that A242481(n) = ((n*(n+1)/2) mod n + sigma(n) mod
 *          n + antisigma(n) mod n) / n = 1.
 * https://oeis.org/A242482
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth integer >1 for which * ((n*(n+1)/2) mod n +
 *            sigma(n) mod n + (n(n+1)/2 - sigma(n)) mod n) == n. * This
 *            reduces to: * * if n is odd: sigma(n) mod n ≠ 0 * * if n is
 *            even: sigma(n) mod n ≤ n/2 * * The sequence is generated by
 *            testing integers in order and storing those * that satisfy...
 * Range:     u8 n <= 171, u16 n <= 5000, u32 n <= 5000, u64 n <= 5000,
 *            u128 n <= 5000, big any n
 * Validated: standard, pass, 82 terms through n = 4372 (2026-11-03)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/mem.h"

/* Compute σ(i) by trial division up to √i. */
static seq_t sigma_of(idx_t n)
{
    seq_t sum = (seq_t)0;
    for (idx_t d = 1; d * d <= n; ++d) {
        if (n % d == 0) {
            sum += (seq_t)d;
            idx_t d2 = n / d;
            if (d2 != d)
                sum += (seq_t)d2;
        }
    }
    return sum;
}

static seq_t *cache = NULL;
static size_t cache_len   = 0;
static size_t cache_cap   = 0;
static idx_t  last_checked = 0;

/*  Return true if n satisfies the condition of the sequence. */
static bool is_candidate(idx_t n)
{
    if (n <= 1)
        return false;

    seq_t sigma = sigma_of(n);          /* σ(n) */
    seq_t b     = sigma % (seq_t)n;     /* σ(n) mod n */

    if ((n & 1) == 0) {                 /* even n */
        return b <= (seq_t)(n / 2);
    } else {                            /* odd n */
        return b != 0;
    }
}

seq_t a(idx_t n)
{
    if (n == 0)
        return 0;                     /* undefined, safer default */

    /* Grow cache to hold at least n terms. */
    if (n > cache_len) {
        size_t needed = n;
        if (needed > cache_cap) {
            size_t new_cap = needed > cache_cap ? needed
                                   : (cache_cap ? cache_cap * 2 : 128);
            seq_t *tmp = mem_resize(seq_t, cache, new_cap);
            if (!tmp) /* allocation failed – unlikely in tests */
                return 0;
            cache = tmp;
            cache_cap = new_cap;
        }

        /* Search for the remaining terms. */
        for (idx_t m = last_checked + 1; ; ++m) {
            if (is_candidate(m)) {
                cache[cache_len++] = (seq_t)m;
                if (cache_len == needed) {
                    last_checked = m;
                    return cache[cache_len - 1];
                }
            }
        }
    }

    return cache[n - 1];
}
